begin;
alter table private.provider_credentials drop constraint provider_credentials_provider_check;
alter table private.provider_credentials add constraint provider_credentials_provider_check check(provider in('paypal','twilio','resend','shopify','browserbase','openai','godaddy'));
-- Extend current definitions in place, retaining all preceding role/optional-step guards.
do $$declare old text;next text;begin
 old:=pg_get_functiondef('public.connect_provider_account(uuid,text,text[],uuid,jsonb,jsonb,uuid,text)'::regprocedure);
 next:=replace(old,'''browserbase'',''openai'')','''browserbase'',''openai'',''godaddy'')');
 next:=replace(next,'if p_provider=''shopify''then','if p_provider in(''shopify'',''godaddy'')then');
 next:=replace(next,'left(p_label,200)','left(coalesce(p_label,''Founder-owned GoDaddy account''),200)');
 if next=old then raise exception 'migration: registrar account extension anchor changed';end if;execute next;
 old:=pg_get_functiondef('public.start_provider_dispatch(uuid,text,text,text,uuid,uuid,text,text,text)'::regprocedure);
 next:=replace(old,'''browserbase_research'',''voice_realtime'')','''browserbase_research'',''voice_realtime'',''registrar_quote'')');
 next:=replace(next,'or(p_kind=''browserbase_research''and p_provider<>''browserbase'')','or(p_kind=''browserbase_research''and p_provider<>''browserbase'')or(p_kind=''registrar_quote''and p_provider<>''godaddy'')');
 if next=old then raise exception 'migration: registrar preparation extension anchor changed';end if;execute next;
end$$;
create table public.registrar_quotes(id uuid primary key,mission_id uuid not null references public.missions(id),account_id uuid not null references public.founder_accounts(id),counterparty_id uuid not null references public.counterparties(id),artifact_version_id uuid not null,task_id uuid not null,quote jsonb not null,expires_at timestamptz not null,created_at timestamptz not null default clock_timestamp(),unique(mission_id,id),unique(mission_id,task_id),unique(artifact_version_id),foreign key(mission_id,artifact_version_id)references public.artifact_versions(mission_id,id));
create table private.registrar_quote_tokens(quote_id uuid primary key references public.registrar_quotes(id),mission_id uuid not null,encrypted jsonb not null);
-- Acknowledgements must commit while the provider lease holds mission/auth rows.
-- No FK is taken on those locked rows; the checked RPC establishes exact lineage.
create table private.registrar_acknowledgements(mission_id uuid not null,authorization_id uuid not null unique,operation_key uuid not null,registration_id uuid not null,operation_id uuid,created_at timestamptz not null default clock_timestamp(),primary key(mission_id,operation_key),unique(mission_id,registration_id));
create table public.domain_registrations(id uuid primary key default gen_random_uuid(),mission_id uuid not null references public.missions(id),quote_id uuid not null,authorization_id uuid not null,receipt_id uuid not null unique,event_id uuid not null,domain text not null,expires_at timestamptz not null,created_at timestamptz not null default clock_timestamp(),unique(mission_id,id),unique(authorization_id),foreign key(mission_id,quote_id)references public.registrar_quotes(mission_id,id),foreign key(mission_id,receipt_id)references public.provider_receipts(mission_id,id),foreign key(mission_id,event_id)references public.events(mission_id,id));
do $$declare t text;begin foreach t in array array['registrar_quotes','domain_registrations']loop
 execute format('alter table public.%I enable row level security',t);execute format('alter table public.%I force row level security',t);execute format('create policy mission_scope on public.%I using(private.owns_mission(mission_id))with check(private.owns_mission(mission_id))',t);
 execute format('create trigger immutable_row before update or delete on public.%I for each row execute function private.immutable_row()',t);execute format('create trigger ledger_revision after insert on public.%I for each row execute function private.record_ledger_revision()',t);execute format('create trigger broadcast_ledger after insert on public.%I for each row execute function private.broadcast_ledger()',t);execute format('grant select on public.%I to founder_role,lead_role,specialist_role,policy_role',t);
end loop;end$$;
create function public.save_registrar_quote(p_mission uuid,p_quote uuid,p_account uuid,p_party uuid,p_task uuid,p_safe jsonb,p_encrypted jsonb)returns uuid language plpgsql security definer set search_path=''as $$declare artifact uuid;version uuid;prior public.registrar_quotes;total numeric;begin
 perform private.require_role(array['policy_role']);perform private.lock_mission(p_mission);perform private.active_mission(p_mission);perform private.assert_safe_content(p_safe);
 if not exists(select from public.provider_account_connections c join public.founder_accounts a on a.id=c.account_id where c.mission_id=p_mission and c.account_id=p_account and c.counterparty_id=p_party and c.provider='godaddy'and a.status='connected'and not exists(select from public.account_revocations r where r.account_id=a.id))then raise exception 'validation: scoped founder registrar account required';end if;
 if not(p_encrypted?&array['iv','ciphertext','tag'])or p_safe?'quoteToken'or p_safe->>'quoteId'is distinct from p_quote::text or p_safe->>'domain'!~'^[a-z0-9.-]+\.[a-z0-9-]+$'or(p_safe->>'period')::integer not between 1 and 10 or private.readiness_date(p_safe->>'expiresAt')<=clock_timestamp()or private.readiness_date(p_safe->>'expiresAt')>clock_timestamp()+interval'15 minutes'or jsonb_typeof(p_safe->'requiredAgreements')is distinct from'array'or jsonb_array_length(p_safe->'requiredAgreements')not between 1 and 20 or length(coalesce(p_safe->>'consentStatement',''))not between 1 and 15000 then raise exception 'validation: complete unexpired immutable registrar quote required';end if;
 total:=(p_safe#>>'{price,value}')::numeric+(select coalesce(sum((f#>>'{fee,value}')::numeric),0)from jsonb_array_elements(p_safe->'fees')f);
 if total<=0 or total<>(p_safe->>'totalMinor')::numeric or p_safe->>'currency'is distinct from p_safe#>>'{price,currencyCode}'or exists(select from jsonb_array_elements(p_safe->'fees')f where f#>>'{fee,currencyCode}'is distinct from p_safe->>'currency')then raise exception 'validation: registrar quote total and all fee currencies must match';end if;
 select*into prior from public.registrar_quotes where mission_id=p_mission and task_id=p_task;if prior.id is not null then if prior.quote<>p_safe or prior.account_id<>p_account or prior.counterparty_id<>p_party then raise exception 'invariant_violation: frozen registrar quote task changed';end if;return prior.artifact_version_id;end if;
 insert into public.artifacts(mission_id,type,outcome,title,actor_id)values(p_mission,'domain_registration','brand','Register exact quoted domain under founder ownership',private.actor_id())returning id into artifact;
 insert into public.artifact_versions(mission_id,artifact_id,version_no,content)values(p_mission,artifact,1,jsonb_build_object('registration',p_safe,'payload',p_safe,'effectIntent',jsonb_build_object('action','registration','effectClass','spend','counterpartyId',p_party,'instrumentId',p_account,'amountMinor',total,'currency',p_safe->>'currency','purpose','Founder-owned domain registration')))returning id into version;
 insert into public.artifact_statuses(mission_id,artifact_version_id,status,actor_id)values(p_mission,version,'proposed',private.actor_id());
 insert into public.registrar_quotes values(p_quote,p_mission,p_account,p_party,version,p_task,p_safe,(p_safe->>'expiresAt')::timestamptz,clock_timestamp());insert into private.registrar_quote_tokens values(p_quote,p_mission,p_encrypted);return version;
end$$;
create function private.check_registrar_version(p_mission uuid,p_version uuid)returns void language plpgsql stable security definer set search_path=''as $$declare q public.registrar_quotes;content jsonb;begin
 select v.content into content from public.artifact_versions v where v.mission_id=p_mission and v.id=p_version;if content#>>'{effectIntent,action}'is distinct from'registration'then return;end if;
 select*into q from public.registrar_quotes where mission_id=p_mission and artifact_version_id=p_version;
 if q.id is null or content->'registration'is distinct from q.quote or content->'payload'is distinct from q.quote or q.expires_at<=clock_timestamp()or content#>>'{effectIntent,counterpartyId}'is distinct from q.counterparty_id::text or content#>>'{effectIntent,instrumentId}'is distinct from q.account_id::text or content#>>'{effectIntent,amountMinor}'is distinct from q.quote->>'totalMinor'or content#>>'{effectIntent,currency}'is distinct from q.quote->>'currency'then raise exception 'needs_approval: original current registrar quote required; never refresh it under an old approval';end if;
 if not exists(select from public.active_decisions d join public.decision_resolutions r on r.decision_id=d.id and r.mission_id=d.mission_id where d.mission_id=p_mission and d.kind='engagement'and d.gate='domain_registration'and d.packet->>'question'=q.quote->>'consentStatement'and r.response in('approve','choose')and r.created_at<=q.expires_at and p_version in(select private.selected_approved_versions(p_mission,d.id)))then raise exception 'needs_approval: explicit founder consent to exact domain term all fees and legal agreements required';end if;
end$$;
create function public.registrar_execution_context(p_mission uuid,p_version uuid,p_historical boolean default false,p_authorization uuid default null,p_token_hash text default null)returns jsonb language plpgsql stable security definer set search_path=''as $$declare q public.registrar_quotes;agreed timestamptz;encrypted jsonb;approval uuid;begin
 perform private.require_role(array['policy_role']);perform private.assert_mission(p_mission);if not p_historical then perform private.check_version(p_mission,p_version);end if;
 select*into strict q from public.registrar_quotes where mission_id=p_mission and artifact_version_id=p_version;
 if p_historical then select a.approval_id into strict approval from public.effect_authorizations a where a.mission_id=p_mission and a.id=p_authorization and a.intent->>'action'='registration'and a.intent->>'artifactVersionId'=p_version::text;
 else select a.id into strict approval from public.approvals a where a.mission_id=p_mission and a.token_hash=p_token_hash and a.binding->>'action'='registration'and a.binding->>'artifactVersionId'=p_version::text and not exists(select from public.approval_consumptions c where c.approval_id=a.id);end if;
 select r.created_at into strict agreed from public.approvals a join public.decision_resolutions r on r.decision_id=a.decision_id and r.mission_id=a.mission_id where a.mission_id=p_mission and a.id=approval and r.response in('approve','choose');
 select t.encrypted into strict encrypted from private.registrar_quote_tokens t where t.mission_id=p_mission and t.quote_id=q.id;return jsonb_build_object('quoteId',q.id,'encrypted',encrypted,'agreedAt',agreed,'quote',q.quote,'accountId',q.account_id,'counterpartyId',q.counterparty_id);
end$$;
create function public.record_registrar_acknowledgement(p_mission uuid,p_key uuid,p_intent_key text,p_registration uuid,p_operation uuid default null)returns void language plpgsql security definer set search_path=''as $$declare a public.effect_authorizations;prior private.registrar_acknowledgements;begin
 perform private.require_role(array['policy_role']);perform private.assert_mission(p_mission);select*into strict a from public.effect_authorizations where mission_id=p_mission and idempotency_key=p_intent_key and intent->>'action'='registration';
 if not exists(select from public.effect_states s where s.mission_id=p_mission and s.authorization_id=a.id and s.status='started')or not exists(select from public.registrar_quotes q where q.mission_id=p_mission and q.artifact_version_id::text=a.intent->>'artifactVersionId')then raise exception 'invariant_violation: durable started registrar effect required';end if;
 insert into private.registrar_acknowledgements values(p_mission,a.id,p_key,p_registration,p_operation,clock_timestamp())on conflict(mission_id,operation_key)do nothing;select*into strict prior from private.registrar_acknowledgements where mission_id=p_mission and operation_key=p_key;if prior.authorization_id<>a.id or prior.registration_id<>p_registration or prior.operation_id is distinct from p_operation then raise exception 'invariant_violation: registrar acknowledgement changed';end if;
end$$;
create function public.pending_registrar_operations(p_mission uuid)returns jsonb language plpgsql stable security definer set search_path=''as $$begin perform private.require_role(array['policy_role']);perform private.assert_mission(p_mission);return coalesce((select jsonb_agg(row_to_json(item))from(select a.id authorization_id,a.intent,ack.registration_id from public.effect_authorizations a left join private.registrar_acknowledgements ack on ack.authorization_id=a.id and ack.mission_id=a.mission_id where a.mission_id=p_mission and a.intent->>'action'='registration'and not exists(select from public.domain_registrations done where done.authorization_id=a.id)order by a.created_at limit 20)item),'[]'::jsonb);end$$;
create function public.file_domain_registration(p_mission uuid,p_authorization uuid,p_event uuid,p_expiry timestamptz)returns uuid language plpgsql security definer set search_path=''as $$declare a public.effect_authorizations;r public.provider_receipts;q public.registrar_quotes;record_id uuid;fact uuid;fx public.effect_fx_conversions;rate public.fx_quotes;begin
 perform private.require_role(array['policy_role']);perform private.lock_mission(p_mission);select*into strict a from public.effect_authorizations where mission_id=p_mission and id=p_authorization;select*into strict r from public.provider_receipts where mission_id=p_mission and authorization_id=a.id and provider='godaddy'and operation='registration';select*into strict q from public.registrar_quotes where mission_id=p_mission and artifact_version_id::text=a.intent->>'artifactVersionId';
 if r.sandbox_mode is distinct from a.sandbox_mode or r.data->>'orderId'is distinct from r.provider_reference or r.data->>'payeeId'is distinct from q.counterparty_id::text or(r.data->>'amountMinor')::numeric is distinct from(q.quote->>'totalMinor')::numeric or r.data->>'currency'is distinct from q.quote->>'currency'or r.data->>'verifiedKind'is distinct from'founder_owned_domain'or r.data->>'verifiedArtifactVersionId'is distinct from q.artifact_version_id::text or not exists(select from private.registrar_acknowledgements ack where ack.mission_id=p_mission and ack.authorization_id=a.id and ack.registration_id::text=r.provider_reference)or not exists(select from public.effect_states s where s.authorization_id=a.id and s.status='performed'and s.receipt_id=r.id)or not exists(select from public.events e where e.id=p_event and e.mission_id=p_mission and e.provider='godaddy'and e.type='registrar.verified_poll'and e.signature_verified and e.payload->>'registrationId'=r.provider_reference and e.payload->>'domain'=q.quote->>'domain'and e.payload->>'artifactVersionId'=q.artifact_version_id::text and(e.payload->>'totalMinor')::numeric=(q.quote->>'totalMinor')::numeric and e.payload->>'currency'=q.quote->>'currency'and(e.payload->>'sandboxMode')::boolean=a.sandbox_mode and(e.payload->>'expiresAt')::timestamptz=p_expiry)then raise exception 'invariant_violation: exact completed registration receipt and verified poll required';end if;
 select registration.id into record_id from public.domain_registrations registration where authorization_id=a.id;if record_id is not null then return record_id;end if;
 insert into public.domain_registrations(mission_id,quote_id,authorization_id,receipt_id,event_id,domain,expires_at)values(p_mission,q.id,a.id,r.id,p_event,q.quote->>'domain',p_expiry)returning domain_registrations.id into record_id;
 select*into fx from public.effect_fx_conversions where authorization_id=a.id;select*into rate from public.fx_quotes where fx.quote_id=fx_quotes.id;
 insert into public.money_ledger(mission_id,kind,amount_minor,currency,basis,envelope,ref_id,receipt_id,confirmation_event_id,sandbox_mode,original_amount_minor,original_currency,fx_quote_id,fx_rate,fx_source,fx_at)values(p_mission,'spent',coalesce(fx.mission_amount_minor,a.amount_minor),coalesce(fx.mission_currency,q.quote->>'currency'),'accepted','Domain registration',record_id,r.id,p_event,a.sandbox_mode,(q.quote->>'totalMinor')::bigint,q.quote->>'currency',rate.id,rate.numerator::numeric/rate.denominator::numeric,rate.source,rate.observed_at);
 fact:=public.append_evidence(p_mission,'brand','founder_owned_domain','verified',jsonb_build_object('domain',q.quote->>'domain','accountId',q.account_id,'artifactVersionId',q.artifact_version_id,'registrationId',r.provider_reference,'expiresAt',p_expiry),'poll','godaddy-registration:'||r.provider_reference,r.id);return record_id;
end$$;
alter function private.check_version(uuid,uuid)rename to check_version_before_registrar;
create function private.check_version(p_mission uuid,p_version uuid)returns void language plpgsql stable security definer set search_path=''as $$begin perform private.check_version_before_registrar(p_mission,p_version);perform private.check_registrar_version(p_mission,p_version);end$$;
revoke all on function private.check_version(uuid,uuid),private.check_version_before_registrar(uuid,uuid)from public;
revoke all on function private.check_registrar_version(uuid,uuid),public.save_registrar_quote(uuid,uuid,uuid,uuid,uuid,jsonb,jsonb),public.registrar_execution_context(uuid,uuid,boolean,uuid,text),public.record_registrar_acknowledgement(uuid,uuid,text,uuid,uuid),public.pending_registrar_operations(uuid),public.file_domain_registration(uuid,uuid,uuid,timestamptz)from public;
grant execute on function public.save_registrar_quote(uuid,uuid,uuid,uuid,uuid,jsonb,jsonb),public.registrar_execution_context(uuid,uuid,boolean,uuid,text),public.record_registrar_acknowledgement(uuid,uuid,text,uuid,uuid),public.pending_registrar_operations(uuid),public.file_domain_registration(uuid,uuid,uuid,timestamptz)to policy_role;
create function public.confirm_owned_resource(p_mission uuid,p_decision uuid,p_version uuid)returns uuid language plpgsql security definer set search_path=''as $$declare confirmation jsonb;v_payload jsonb;ref text;id uuid;begin
 perform private.require_role(array['founder_role']);perform private.lock_mission(p_mission);
 select v.content->'founderConfirmation'into confirmation from public.artifact_versions v join public.active_decisions d on d.mission_id=v.mission_id and d.id=p_decision where v.id=p_version and v.mission_id=p_mission and d.kind='engagement'and d.gate='account_ownership'and d.packet->>'question'=v.content#>>'{founderConfirmation,statement}'and p_version in(select private.selected_approved_versions(p_mission,p_decision))and private.readiness_current_approved(p_mission,p_version);
 v_payload:=confirmation->'payload';if confirmation is null or confirmation->>'kind'is distinct from'owned_resource'or v_payload->>'kind'not in('domain','handles')or length(trim(coalesce(v_payload->>'resource','')))not between 3 and 253 or jsonb_typeof(v_payload->'sourceEvidenceIds')is distinct from'array'or jsonb_array_length(v_payload->'sourceEvidenceIds')not between 1 and 20 or not exists(select from public.founder_accounts a join public.missions m on m.founder_id=a.founder_id where m.id=p_mission and a.id::text=v_payload->>'accountId')then raise exception 'needs_approval: exact founder-owned account resource and reviewed ownership sources required';end if;
 for ref in select jsonb_array_elements_text(v_payload->'sourceEvidenceIds')loop if not exists(select from public.evidence e where e.mission_id=p_mission and e.id::text=ref and e.kind in('account_ownership_document','domain_ownership_document','handle_ownership_document')and e.trust in('claimed','verified','founder_confirmed')and e.payload->>'accountId'=v_payload->>'accountId'and e.payload->>'resource'=v_payload->>'resource'and e.source_type in('document','message','url')and length(e.source_reference)>0 and not exists(select from public.stale_marks s where s.node_id=e.id)and not exists(select from public.evidence n where n.supersedes_id=e.id))then raise exception 'needs_approval: current actual ownership document required; availability alone is not ownership';end if;end loop;
 select e.id into id from public.evidence e where e.mission_id=p_mission and e.source_reference='manual-ownership:'||p_decision::text||':'||p_version::text;if id is not null then return id;end if;
 id:=public.append_evidence(p_mission,'brand',case when v_payload->>'kind'='domain'then'founder_owned_domain'else'founder_owned_handles'end,'founder_confirmed',v_payload||jsonb_build_object('statement',confirmation->>'statement','decisionId',p_decision,'artifactVersionId',p_version,'confirmedAt',clock_timestamp()),'founder','manual-ownership:'||p_decision::text||':'||p_version::text);
 insert into public.dependencies(mission_id,upstream_id,dependent_id,reason)values(p_mission,p_version,id,'exact manual ownership confirmation'),(p_mission,p_decision,id,'founder ownership decision');for ref in select jsonb_array_elements_text(v_payload->'sourceEvidenceIds')loop insert into public.dependencies(mission_id,upstream_id,dependent_id,reason)values(p_mission,ref::uuid,id,'actual reviewed ownership document')on conflict do nothing;end loop;return id;
end$$;
revoke all on function public.confirm_owned_resource(uuid,uuid,uuid)from public;grant execute on function public.confirm_owned_resource(uuid,uuid,uuid)to founder_role;
commit;
